description:
Change under review. Task: add a `--json` flag to `agents list` that prints the agents as a JSON array of `{ name, mode }` objects instead of the table. Acceptance: without the flag the table output is unchanged; with it the output is valid JSON with exactly those two fields per agent; `formatAgentsList` has a test for each path.

Added files are shown in full. For changed files, only the changed region is shown; the rest of the file is unchanged and compiles.

`src/agents/summary.ts` (unchanged, shown for context):
```ts
3 export interface AgentSummary {
4   name: string;
5   mode: "primary" | "subagent" | "all";
6   description?: string;
7 }
```

`src/commands/agents-list.ts` (changed, lines 1-14):
```ts
1 import type { AgentSummary } from "../agents/summary.js";
2 import { renderTable } from "../ui/table.js";
3
4 export interface AgentsListArgs {
5   json: boolean;
6 }
7
8 export function formatAgentsList(agents: AgentSummary[], args: AgentsListArgs): string {
9   if (args.json) {
10     return JSON.stringify(agents.map(({ name, mode }) => ({ name, mode })));
11   }
12   return renderTable(["Name", "Mode"], agents.map((agent) => [agent.name, agent.mode]));
13 }
```

`src/cli/agents.ts` (changed, lines 21-25):
```ts
21   .command("list")
22   .option("--json", "Print the agents as JSON", false)
23   .action((opts: { json: boolean }) => {
24     print(formatAgentsList(listAgents(), { json: opts.json }));
25   });
```

`src/commands/__tests__/agents-list.test.ts` (added):
```ts
1 import { expect, test } from "bun:test";
2 import { renderTable } from "../../ui/table.js";
3 import { formatAgentsList } from "../agents-list.js";
4
5 const agents = [
6   { name: "loom", mode: "primary" as const, description: "Orchestrator" },
7   { name: "shuttle", mode: "subagent" as const },
8 ];
9
10 test("without --json the table is unchanged", () => {
11   expect(formatAgentsList(agents, { json: false })).toBe(
12     renderTable(["Name", "Mode"], [["loom", "primary"], ["shuttle", "subagent"]]),
13   );
14 });
15
16 test("--json prints name and mode only", () => {
17   expect(JSON.parse(formatAgentsList(agents, { json: true }))).toEqual([
18     { name: "loom", mode: "primary" },
19     { name: "shuttle", mode: "subagent" },
20   ]);
21 });
```

